import {
  foreignKey,
  integer,
  jsonb,
  pgTable,
  primaryKey,
  text,
  timestamp,
  unique,
  uuid,
} from "drizzle-orm/pg-core";
import { users } from "./users.ts";
import { gameServerCredentials } from "./game-server-credentials.ts";

/**
 * One batch of currency and item changes the game server applied for a player in one title. The request id is generated by the
 * game server per batch, so a retry of the same batch carries the same id. The unique key is what makes a retry replay instead
 * of applying twice. A batch is written in the same transaction as its balances, so a refused batch leaves no row.
 * An estate action also stores its request and its response on the batch, so a replay returns the stored response.
 */
export const titleLedgerBatches = pgTable(
  "title_ledger_batches",
  {
    id: uuid("id").defaultRandom().notNull().primaryKey(),
    userId: uuid("user_id").notNull(),
    title: text("title").notNull(),
    requestId: uuid("request_id").notNull(),
    gameServerId: uuid("game_server_id").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true }).defaultNow().notNull(),
    request: jsonb("request").$type<Record<string, unknown>>(),
    response: jsonb("response").$type<Record<string, unknown>>(),
  },
  (t) => [
    unique("title_ledger_batches_user_id_title_request_id_key").on(t.userId, t.title, t.requestId),
    foreignKey({
      name: "title_ledger_batches_user_id_users_id_fk",
      columns: [t.userId],
      foreignColumns: [users.id],
    }).onDelete("cascade"),
    foreignKey({
      name: "title_ledger_batches_game_server_id_game_server_credentials_id_fk",
      columns: [t.gameServerId],
      foreignColumns: [gameServerCredentials.id],
    }),
  ],
);

/**
 * One change a batch made to one currency or item: its net delta, the balance it left, and why. A batch names each id once, so
 * the primary key is (batch, item). `kind` says which table the id belongs to. `reason` joins the reasons of the changes that were
 * netted into this row with "; ". It is null only for rows written before reasons were kept.
 */
export const titleLedgerEntries = pgTable(
  "title_ledger_entries",
  {
    batchId: uuid("batch_id").notNull(),
    kind: text("kind").$type<"currency" | "item">().notNull(),
    itemId: uuid("item_id").notNull(),
    delta: integer("delta").notNull(),
    balanceAfter: integer("balance_after").notNull(),
    reason: text("reason"),
  },
  (t) => [
    primaryKey({
      name: "title_ledger_entries_batch_id_item_id_pk",
      columns: [t.batchId, t.itemId],
    }),
    foreignKey({
      name: "title_ledger_entries_batch_id_title_ledger_batches_id_fk",
      columns: [t.batchId],
      foreignColumns: [titleLedgerBatches.id],
    }).onDelete("cascade"),
  ],
);
